# index.html patch instructions
# Four surgical changes — nothing else touches the file.

# ════════════════════════════════════════════════════════════════
# CHANGE 1 — Add four <script> tags in the <head>, after vis-network
# ════════════════════════════════════════════════════════════════

FIND (in <head>):
  <script src="/static/vis-network.min.js"></script>
  <link rel="stylesheet" href="/static/vis-network.min.css">

REPLACE WITH:
  <script src="/static/vis-network.min.js"></script>
  <link rel="stylesheet" href="/static/vis-network.min.css">
  <script src="/static/graph-viewport.js"></script>
  <script src="/static/minimap.js"></script>
  <script src="/static/fullscreen.js"></script>
  <script src="/static/graph-renderer.js"></script>

(Copy graph-viewport.js, minimap.js, fullscreen.js, graph-renderer.js
 to your Flask /static/ folder alongside vis-network.min.js)


# ════════════════════════════════════════════════════════════════
# CHANGE 2 — Replace openGraphFS() and closeGraphFS() calls in HTML
# ════════════════════════════════════════════════════════════════
# These are already wired correctly via graph-integration.js globals.
# No change needed in the HTML attributes themselves.


# ════════════════════════════════════════════════════════════════
# CHANGE 3 — Remove the old second <script> block entirely
# ════════════════════════════════════════════════════════════════

FIND (the entire second <script> block — starts with):
  <script>
  // ── PHASE 9E — KNOWLEDGE GRAPH ───────────────────────────────────────────────
  let psbNetwork   = null;
  ...

  (ends with the closing </script> of that block)

REPLACE WITH a single tag:
  <script src="/static/graph-integration.js"></script>


# ════════════════════════════════════════════════════════════════
# CHANGE 4 — (Optional but recommended) showV() tweak
# ════════════════════════════════════════════════════════════════
# In the first <script> block, the showV() function references $('main-area')
# which doesn't exist (the element is just <main>). Change:

FIND:
    const mainArea=$('main-area');
    const gsf=$('graph-sticky-footer');
    if(v==='view-graph'){
        if(mainArea){ mainArea.classList.add('graph-active'); mainArea.style.padding='0'; mainArea.style.overflow='hidden'; mainArea.style.position='relative'; }
        if(gsf) gsf.classList.add('visible');
        loadGS();
        setTimeout(()=>{ if(!psbNetwork) initGraph('all'); }, 350);
    } else {
        if(mainArea){ mainArea.classList.remove('graph-active'); mainArea.style.padding=''; mainArea.style.overflow=''; mainArea.style.position=''; }
        if(gsf) gsf.classList.remove('visible');
    }

REPLACE WITH:
    const mainEl = document.querySelector('main');
    if(v==='view-graph'){
        if(mainEl){ mainEl.classList.add('graph-active'); mainEl.style.padding='0'; mainEl.style.overflow='hidden'; mainEl.style.position='relative'; }
        loadGS();
        // Let the CSS layout settle before measuring the container
        requestAnimationFrame(() => requestAnimationFrame(() => {
            if(typeof initGraph === 'function') initGraph('all');
        }));
    } else {
        if(mainEl){ mainEl.classList.remove('graph-active'); mainEl.style.padding=''; mainEl.style.overflow=''; mainEl.style.position=''; }
    }


# ════════════════════════════════════════════════════════════════
# DEPLOYMENT CHECKLIST
# ════════════════════════════════════════════════════════════════

cp graph-viewport.js    /path/to/your/flask/static/
cp minimap.js           /path/to/your/flask/static/
cp fullscreen.js        /path/to/your/flask/static/
cp graph-renderer.js    /path/to/your/flask/static/
cp graph-integration.js /path/to/your/flask/static/

# Then apply the 4 changes above to index.html (or templates/index.html).


# ════════════════════════════════════════════════════════════════
# WHAT EACH FIX ADDRESSES
# ════════════════════════════════════════════════════════════════

FIX 1 — Container sizing before vis.

